args.command:
mkdir -p /output/lib && node -e '
const fs = require("fs");
const lines = fs.readFileSync("/tmp/probe1.txt", "utf8").trim().split("\n");
const suffixes = [["1,234.5679",4],["1,234.568",3],["1,234.57",2],["1,235",0]];
const entries = [];
for (const line of lines) {
  const [code, rc, out] = line.split("|");
  if (rc !== "0") throw new Error("bad rc for " + code);
  let sym = null, digits = null;
  for (const [sfx, d] of suffixes) {
    if (out.endsWith(sfx)) { sym = out.slice(0, out.length - sfx.length); digits = d; break; }
  }
  if (sym === null) throw new Error("no suffix match: " + line);
  if (!sym) throw new Error("empty symbol: " + line);
  entries.push([code, sym, digits]);
}
entries.sort((a,b)=>a[0].localeCompare(b[0]));
let body = entries.map(([c,s,d]) => `  ${JSON.stringify(c)}: [${JSON.stringify(s)}, ${d}],`).join("\n");
const content = `// Currency data reconstructed black-box from the reference implementation.\n// Each entry maps an ISO-like code to [symbol (en locale), fraction digits].\nexport const CURRENCIES = {\n${body}\n};\n`;
fs.writeFileSync("/tmp/currencies_body.txt", content);
console.log(entries.length + " currencies written");
console.log(entries.filter(e=>e[2]!==2).map(e=>e.join(":")).join(" "));
'

