// Replicates CPython's float() parsing and repr()/str() formatting,
// which the reference pipeline relies on (argparse type=float, then
// Decimal(str(amount)) inside Money).

const DIGITS = '\\d(?:_?\\d)*';
const NUMERIC_RE = new RegExp(
  `^[+-]?(?:(?:${DIGITS})(?:\\.${DIGITS}?)?|\\.${DIGITS})(?:[eE][+-]?${DIGITS})?$`
);
const SPECIAL_RE = /^[+-]?(inf(?:inity)?|nan)$/i;

// Mimics Python's float(str). Returns { ok: true, value } or { ok: false }.
export function parsePythonFloat(raw) {
  const s = raw.replace(/^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g, '');
  if (SPECIAL_RE.test(s)) {
    const neg = s.startsWith('-');
    if (/nan/i.test(s.replace(/^[+-]/, ''))) return { ok: true, value: NaN };
    return { ok: true, value: neg ? -Infinity : Infinity };
  }
  if (!NUMERIC_RE.test(s)) return { ok: false };
  const cleaned = s.replace(/_/g, '');
  const value = Number(cleaned);
  if (Number.isNaN(value)) return { ok: false };
  return { ok: true, value };
}

// Mimics Python's str(float) (shortest round-trip, CPython formatting rules):
// fixed notation for -4 <= exponent < 16, scientific notation otherwise,
// always a decimal point in fixed notation, exponent signed and >= 2 digits.
export function pythonFloatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  let sign = '';
  let n = value;
  if (n < 0 || Object.is(n, -0)) {
    sign = '-';
    n = Math.abs(n);
  }
  if (n === 0) return sign + '0.0';

  // Shortest round-trip digits via toExponential(): "6.2498e+2".
  const m = n.toExponential().match(/^(\d)(?:\.(\d+))?e([+-]\d+)$/);
  const digits = m[1] + (m[2] || '');
  const exp = parseInt(m[3], 10); // value = digits[0].digits[1:] * 10^exp

  if (exp >= -4 && exp < 16) {
    if (exp >= digits.length - 1) {
      // Integer with trailing zeros; Python always appends ".0".
      return sign + digits + '0'.repeat(exp - digits.length + 1) + '.0';
    }
    if (exp >= 0) {
      return sign + digits.slice(0, exp + 1) + '.' + digits.slice(exp + 1);
    }
    return sign + '0.' + '0'.repeat(-exp - 1) + digits;
  }
  const mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
  const esign = exp < 0 ? '-' : '+';
  const eabs = String(Math.abs(exp)).padStart(2, '0');
  return sign + mantissa + 'e' + esign + eabs;
}

