// Decimal-string arithmetic and currency formatting, replicating the
// behavior of Decimal(str(amount)) + Babel's format_currency:
// quantize to the currency's fraction digits with ROUND_HALF_EVEN,
// thousands grouping, and locale-specific symbol placement.

// Parses a Python-repr decimal string (e.g. "-1.5e+16") into
// { negative, int, frac } with plain digit strings, or a special value.
export function parseDecimalRepr(repr) {
  if (repr === 'nan') return { special: 'nan', negative: false };
  if (repr === 'inf') return { special: 'inf', negative: false };
  if (repr === '-inf') return { special: 'inf', negative: true };

  let negative = false;
  let s = repr;
  if (s.startsWith('-')) {
    negative = true;
    s = s.slice(1);
  }

  let mantissa = s;
  let exp = 0;
  const eIdx = s.indexOf('e');
  if (eIdx !== -1) {
    mantissa = s.slice(0, eIdx);
    exp = parseInt(s.slice(eIdx + 1), 10);
  }

  let intPart = '';
  let fracPart = '';
  const dotIdx = mantissa.indexOf('.');
  if (dotIdx === -1) {
    intPart = mantissa;
  } else {
    intPart = mantissa.slice(0, dotIdx);
    fracPart = mantissa.slice(dotIdx + 1);
  }

  // Shift the decimal point by exp places.
  const digits = intPart + fracPart;
  let point = intPart.length + exp;
  if (point <= 0) {
    intPart = '0';
    fracPart = '0'.repeat(-point) + digits;
  } else if (point >= digits.length) {
    intPart = digits + '0'.repeat(point - digits.length);
    fracPart = '';
  } else {
    intPart = digits.slice(0, point);
    fracPart = digits.slice(point);
  }

  intPart = intPart.replace(/^0+(?=\d)/, '');
  return { special: null, negative, int: intPart, frac: fracPart };
}

// Increments a digit string by one (used when rounding up).
function incrementDigits(digits) {
  const arr = digits.split('');
  for (let i = arr.length - 1; i >= 0; i--) {
    if (arr[i] !== '9') {
      arr[i] = String.fromCharCode(arr[i].charCodeAt(0) + 1);
      return arr.join('');
    }
    arr[i] = '0';
  }
  return '1' + arr.join('');
}

// Quantizes int/frac to `places` fraction digits using ROUND_HALF_EVEN.
export function quantizeHalfEven(intPart, fracPart, places) {
  let kept = fracPart.slice(0, places);
  const dropped = fracPart.slice(places);

  let roundUp = false;
  if (dropped.length > 0) {
    const first = dropped[0];
    if (first > '5') {
      roundUp = true;
    } else if (first < '5') {
      roundUp = false;
    } else if (/[1-9]/.test(dropped.slice(1))) {
      roundUp = true;
    } else {
      // Exactly half: round to even.
      const lastKept = places > 0 ? kept[places - 1] : intPart[intPart.length - 1];
      roundUp = (lastKept.charCodeAt(0) - 48) % 2 === 1;
    }
  }

  if (roundUp) {
    const combined = intPart + kept.padEnd(places, '0');
    const bumped = incrementDigits(combined);
    intPart = bumped.slice(0, bumped.length - places) || '0';
    kept = bumped.slice(bumped.length - places);
  } else {
    kept = kept.padEnd(places, '0');
  }
  return { int: intPart, frac: kept };
}

// Inserts a thousands separator every three digits.
export function groupDigits(intPart, sep) {
  if (!sep) return intPart;
  let out = '';
  while (intPart.length > 3) {
    out = sep + intPart.slice(-3) + out;
    intPart = intPart.slice(0, -3);
  }
  return intPart + out;
}

// Formats a Python-repr decimal string as a currency amount.
// rules: { groupSep, decimalSep, placement: 'prefix' | 'prefix-nbsp' | 'suffix-nbsp' }
export function formatMoney(repr, symbol, digits, rules) {
  const parsed = parseDecimalRepr(repr);
  const nbsp = ' ';

  let numberText;
  if (parsed.special === 'inf') {
    numberText = '∞';
  } else if (parsed.special === 'nan') {
    numberText = 'NaN' + (digits > 0 ? rules.decimalSep + '0'.repeat(digits) : '');
  } else {
    const q = quantizeHalfEven(parsed.int, parsed.frac, digits);
    numberText = groupDigits(q.int, rules.groupSep);
    if (digits > 0) numberText += rules.decimalSep + q.frac;
  }

  const neg = parsed.negative ? '-' : '';
  if (rules.placement === 'suffix-nbsp') {
    return neg + numberText + nbsp + symbol;
  }
  if (rules.placement === 'prefix-nbsp') {
    return neg + symbol + nbsp + numberText;
  }
  return neg + symbol + numberText;
}

