// Locale resolution and formatting rules, mirroring Babel's
// default_locale() environment lookup and the CLDR data for the
// locales relevant to the reference implementation's behavior.

const NBSP = ' ';
const NNBSP = ' ';

// Formatting rules per locale family. `overrides` maps currency codes to
// symbols that differ from the shared (en) table.
const LOCALE_RULES = {
  en: {
    groupSep: ',',
    decimalSep: '.',
    placement: 'prefix',
    overrides: {},
  },
  'en_US_POSIX': {
    groupSep: null, // POSIX locale applies no thousands grouping
    decimalSep: '.',
    placement: 'prefix-nbsp',
    overrides: {},
  },
  zh: {
    groupSep: ',',
    decimalSep: '.',
    placement: 'prefix',
    overrides: { USD: 'US$', CNY: '¥', JPY: 'JP¥', CAD: 'CA$' },
  },
  de: {
    groupSep: '.',
    decimalSep: ',',
    placement: 'suffix-nbsp',
    overrides: {},
  },
  fr: {
    groupSep: NNBSP,
    decimalSep: ',',
    placement: 'suffix-nbsp',
    overrides: { USD: '$US', CAD: '$CA', GBP: '£GB', CNY: 'CNY', JPY: 'JPY' },
  },
  ja: {
    groupSep: ',',
    decimalSep: '.',
    placement: 'prefix',
    overrides: { JPY: '￥', CNY: '元' },
  },
};

// Mirrors babel.core.default_locale(): checks LANGUAGE, LC_ALL, LC_CTYPE,
// LANG in order; strips encoding/modifier; maps C/POSIX to en_US_POSIX;
// returns null when no usable locale identifier is found (Babel then fails).
export function resolveLocale(env) {
  for (const name of ['LANGUAGE', 'LC_ALL', 'LC_CTYPE', 'LANG']) {
    let value = env[name];
    if (!value) continue;
    if (name === 'LANGUAGE' && value.includes(':')) {
      value = value.split(':')[0];
    }
    if (value.includes('.')) {
      value = value.split('.')[0];
    }
    if (value === 'C' || value === 'POSIX') {
      value = 'en_US_POSIX';
    }
    value = value.split('@')[0].replace(/-/g, '_');
    if (/^[A-Za-z]{2,3}(_[A-Za-z0-9]+)*$/.test(value)) {
      return value;
    }
  }
  return null;
}

// Returns the formatting rules for a resolved locale identifier.
export function getLocaleRules(localeId) {
  if (localeId === 'en_US_POSIX') return LOCALE_RULES['en_US_POSIX'];
  const language = localeId.split('_')[0].toLowerCase();
  return LOCALE_RULES[language] || LOCALE_RULES.en;
}

export { NBSP, NNBSP };

