// Reimplements the observable behavior of moneyed.Money: construction from
// (amount, currency code) and its localized string representation.

import { CURRENCIES } from './currencies.mjs';
import { pythonFloatRepr } from './pyfloat.mjs';
import { formatMoney } from './decimal_format.mjs';
import { resolveLocale, getLocaleRules } from './locales.mjs';

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
