// Minimal reimplementation of the argparse behavior used by the reference
// script: two required options (--amount with type=float, --currency with
// type=str) plus -h/--help, with argparse-compatible error handling.

import { parsePythonFloat } from './pyfloat.mjs';

const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

const LONG_OPTIONS = ['--help', '--amount', '--currency'];

function prog() {
  const script = process.argv[1] || '';
  const base = script.split(/[\\/]/).pop();
  return base || 'test10.mjs';
}

function usageLine() {
  return `usage: ${prog()} [-h] --amount AMOUNT --currency CURRENCY`;
}

function printHelpAndExit() {
  process.stdout.write(
    usageLine() +
      '\n\noptions:\n' +
      '  -h, --help           show this help message and exit\n' +
      '  --amount AMOUNT\n' +
      '  --currency CURRENCY\n'
  );
  process.exit(0);
}

function errorAndExit(message) {
  process.stderr.write(usageLine() + '\n' + `${prog()}: error: ${message}\n`);
  process.exit(2);
}

// Mirrors argparse's test for whether a token can serve as an option value
// (the parser defines no options that look like negative numbers).
function looksLikeValue(token) {
  if (!token.startsWith('-')) return true;
  if (token === '-') return true;
  if (NEGATIVE_NUMBER_RE.test(token)) return true;
  if (token.includes(' ')) return true;
  return false;
}

function resolveLongOption(name) {
  if (LONG_OPTIONS.includes(name)) return name;
  const matches = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) {
    errorAndExit(`ambiguous option: ${name} could match ${matches.join(', ')}`);
  }
  return null;
}

// Parses process.argv (minus node/script). Returns { amount, currency }
// where amount is a JS number with Python float() semantics.
export function parseArgs(argv) {
  const tokens = argv.slice(2);
  const values = {};
  const extras = [];
  let onlyPositionals = false;

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (onlyPositionals) {
      extras.push(token);
      continue;
    }
    if (token === '--') {
      onlyPositionals = true;
      continue;
    }

    let name = null;
    let inlineValue = null;

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const rawName = eq === -1 ? token : token.slice(0, eq);
      name = resolveLongOption(rawName);
      if (name === null) {
        extras.push(token);
        continue;
      }
      if (eq !== -1) inlineValue = token.slice(eq + 1);
    } else if (token === '-h') {
      name = '--help';
    } else if (token.startsWith('-') && !looksLikeValue(token)) {
      extras.push(token);
      continue;
    } else {
      extras.push(token); // no positionals are defined
      continue;
    }

    if (name === '--help') {
      printHelpAndExit();
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
    } else {
      const next = tokens[i + 1];
      if (next === undefined || !looksLikeValue(next)) {
        errorAndExit(`argument ${name}: expected one argument`);
      }
      raw = next;
      i++;
    }

    if (name === '--amount') {
      const parsed = parsePythonFloat(raw);
      if (!parsed.ok) {
        errorAndExit(`argument --amount: invalid float value: '${raw}'`);
      }
      values.amount = parsed.value;
    } else {
      values.currency = raw;
    }
  }

  const missing = [];
  if (values.amount === undefined) missing.push('--amount');
  if (values.currency === undefined) missing.push('--currency');
  if (missing.length > 0) {
    errorAndExit(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    errorAndExit(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return values;
}

